pub fn prune(&mut self, prune_slot: Slot) {
    self.data_columns
        .retain(|_, (_, slot, _)| prune_slot <= *slot);
}

pub fn prune_persisted(&mut self, prune_slot: Slot) {
    self.data_columns
        .retain(|_, (_, slot, persisted)| !*persisted || prune_slot <= *slot);
}

